// Graphic composition with LIVE Hebrew text and the ORIGINAL logo layer (never regenerated by an image model).
// Output is an editable SVG source; the AI image is only the background layer.
export const FORMATS = { square: [1080, 1080], story: [1080, 1920], portrait: [1080, 1350], landscape: [1920, 1080], pin: [1000, 1500] } as const;
const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));
function wrap(text: string, max: number) { const words = text.split(/\s+/); const lines: string[] = []; let cur = '';
  for (const w of words) { if ((cur + ' ' + w).trim().length > max) { if (cur) lines.push(cur); cur = w; } else cur = (cur + ' ' + w).trim(); } if (cur) lines.push(cur); return lines; }
export function composeSvg(p: { format: keyof typeof FORMATS; headline: string; sub?: string; cta?: string; bgDataUri?: string; logoUrl: string }) {
  const [W, H] = FORMATS[p.format]; const safe = Math.round(W * 0.07); const hl = wrap(p.headline, p.format === 'landscape' ? 26 : 16).slice(0, 4);
  const fs = Math.round(W * (p.format === 'landscape' ? 0.05 : 0.082)); const sub = p.sub ? wrap(p.sub, 34).slice(0, 3) : [];
  const top = H - safe - (p.cta ? 120 : 40) - sub.length * fs * 0.5 - hl.length * fs * 1.1;
  return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" direction="rtl">
<defs><style>@import url('https://fonts.googleapis.com/css2?family=Assistant:wght@600;800;900&amp;display=swap');text{font-family:Assistant,sans-serif}</style>
<linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#4BE7FF"/><stop offset=".45" stop-color="#00CFFF"/><stop offset="1" stop-color="#0094BD"/></linearGradient>
<linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset=".35" stop-color="#0B1320" stop-opacity="0"/><stop offset="1" stop-color="#0B1320" stop-opacity=".82"/></linearGradient></defs>
<g id="layer-background"><rect width="${W}" height="${H}" fill="url(#g)"/>${p.bgDataUri ? `<image href="${p.bgDataUri}" width="${W}" height="${H}" preserveAspectRatio="xMidYMid slice"/>` : ''}<rect width="${W}" height="${H}" fill="url(#fade)"/></g>
<g id="layer-logo"><rect x="${W - safe - 260}" y="${safe}" width="260" height="70" rx="20" fill="#fff"/><image href="${esc(p.logoUrl)}" x="${W - safe - 245}" y="${safe + 12}" width="230" height="46" preserveAspectRatio="xMidYMid meet"/></g>
<g id="layer-text" text-anchor="end">${hl.map((l, i) => `<text x="${W - safe}" y="${top + (i + 1) * fs * 1.1}" font-size="${fs}" font-weight="900" fill="#fff">${esc(l)}</text>`).join('')}
${sub.map((l, i) => `<text x="${W - safe}" y="${top + hl.length * fs * 1.1 + (i + 1) * fs * 0.55 + 12}" font-size="${Math.round(fs * 0.42)}" font-weight="600" fill="#EAF7FF">${esc(l)}</text>`).join('')}</g>
${p.cta ? `<g id="layer-cta"><rect x="${W - safe - Math.max(220, p.cta.length * 26)}" y="${H - safe - 90}" width="${Math.max(220, p.cta.length * 26)}" height="76" rx="38" fill="#E8F401"/><text x="${W - safe - 34}" y="${H - safe - 40}" font-size="34" font-weight="800" fill="#0B1320" text-anchor="end">${esc(p.cta)}</text></g>` : ''}
</svg>`;
}
